import {GENKI_UNITS,GENKI_UNIT_BY_ID,GENKI_QUESTION_BY_ID,GENKI_WORD_BY_ID,GENKI_AUDIO} from './genki-content.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function ordered(items,seed){let hash=2166136261;for(const char of String(seed))hash=Math.imul(hash^char.charCodeAt(0),16777619)>>>0;return items.map((value,index)=>{hash=(Math.imul(hash,1664525)+1013904223)>>>0;return {value,index,key:hash};}).sort((a,b)=>a.key-b.key);}
const wordPlayer=id=>`<div class="kana-audio-controls"><button class="audio-button" data-action="genki-play" data-id="${id}">Послушать</button><button class="audio-button audio-slow" data-action="genki-play" data-id="${id}" data-slow="true">Медленно</button></div><p class="audio-source-note">Оригинальная запись Genki</p>`;
const player=(id,label='Запись Genki')=>GENKI_AUDIO[id]?`<div class="genki-player"><span>${esc(label)}</span><audio controls preload="none" src="${GENKI_AUDIO[id]}" aria-label="${esc(label)}"></audio></div>`:'';
export function genkiHome(state){
 const g=state.genki,active=g.session&&g.session.phase!=='result',seen=Object.keys(g.mastery).length;
 return `<div class="page-heading"><div><h1>Genki 1 — Знакомство</h1><p>Глава 1 · второе издание · 7 занятий</p></div></div><section class="study-summary"><div><strong>${g.completed.length}<small> / 7</small></strong><span>занятий пройдено</span></div><div><strong>28</strong><span>слов и выражений</span></div><div><strong>${g.mistakes.length}</strong><span>ошибок к повторению</span></div></section>${active?`<section class="continue-panel"><div class="continue-copy"><span class="eyebrow">ТЕКУЩЕЕ ЗАНЯТИЕ</span><h2>${esc(GENKI_UNIT_BY_ID[g.session.unitId]?.label||'Закрепление Genki')}</h2></div><button class="primary" data-action="genki-resume">Продолжить</button></section>`:''}<div class="review-actions"><button class="secondary" data-action="genki-start" data-id="g1-review" ${!seen&&!g.completed.length?'disabled':''}>Закрепить изученное</button><button class="secondary" data-action="genki-start" data-id="g1-errors" ${!g.mistakes.length?'disabled':''}>Ошибки <span class="count">${g.mistakes.length}</span></button></div><div class="genki-unit-list">${GENKI_UNITS.map((u,i)=>`<button class="lesson-card genki-unit ${g.completed.includes(u.id)?'complete':''}" data-action="genki-start" data-id="${u.id}"><span class="unit-number">${String(i+1).padStart(2,'0')}</span><span class="lesson-card-copy"><strong>${u.label}</strong><span class="muted">${u.subtitle} · ${u.minutes} мин</span></span><span class="unit-state">${g.completed.includes(u.id)?'✓':'›'}</span></button>`).join('')}</div><p class="tiny-note genki-source">Genki I, 2-е издание, глава 1, стр. 38–57. Объяснения и тренажёр — на русском. Оригинальные записи доступны после входа.</p>`;
}
export function genkiLesson(state,{syncMarkup='',draft=[]}={}){
 const g=state.genki,s=g.session;if(!s)return '';const unit=GENKI_UNIT_BY_ID[s.unitId],title=unit?.label||(s.unitId==='g1-errors'?'Ошибки Genki':'Закрепление Genki');let body='';
 if(s.phase==='learn'){
  const card=unit.cards[s.cardIndex],word=card.word&&GENKI_WORD_BY_ID[card.word];
  body=`<section class="genki-learning"><span class="eyebrow">GENKI 1 · ${s.cardIndex+1} / ${unit.cards.length}</span><h1>${esc(card.title)}</h1><div class="surface genki-rule-card"><div class="genki-japanese ${word?'genki-word':''}" lang="ja">${esc(card.ja)}</div><p class="genki-translation" ${word?'lang="ja"':''}>${esc(card.ru)}</p>${word?`<p class="muted">${word.romaji}</p>`:''}${card.audio?(word?wordPlayer(card.audio):player(card.audio,`Genki · диалог ${s.cardIndex+1}`)):''}<p class="genki-explanation">${esc(card.explanation)}</p></div><button class="primary wide" data-action="genki-learn-next">${s.cardIndex+1===unit.cards.length?'К упражнениям':'Дальше'}</button><button class="text-button learn-skip" data-action="genki-skip">Сразу к упражнениям</button>${unit.audio?`<details class="genki-extra"><summary>${unit.id==='g1-time'?'Послушать часы в Genki':'Послушать словарь Genki'}</summary>${player(unit.audio,'Genki · стр. '+unit.pages)}</details>`:''}</section>`;
 }else if(s.phase==='result'){
  body=`<section class="result-content"><h1>Занятие завершено</h1><div class="result-stats"><div><strong>${s.firstCorrect}<small> / ${s.firstAnswers}</small></strong><span>с первой попытки</span></div><div><strong>${Math.round(s.firstCorrect/Math.max(1,s.firstAnswers)*100)}<small>%</small></strong><span>точность</span></div><div><strong>${s.bonus?'+20':g.completed.length}</strong><span>${s.bonus?'XP за новое занятие':'занятий пройдено'}</span></div></div>${g.mistakes.length?`<p>Ошибок к повторению: ${g.mistakes.length}.</p>`:''}<button class="primary wide" data-action="genki-finish">К занятиям Genki</button><button class="text-button learn-skip" data-action="genki-repeat" data-id="${s.unitId}">Повторить занятие</button></section>`;
 }else{
  const item=s.questions[s.index],q=GENKI_QUESTION_BY_ID[item.id],f=s.feedback,seed=q.id+':'+s.startedAt;
  let inputs='';
  if(q.type==='choice')inputs=`<div class="genki-options">${ordered(q.options,seed).map(({value},i)=>`<button class="answer-option genki-option ${f?(value===q.answer?'answer-correct':value===f.value?'answer-wrong':'answer-muted'):''}" data-action="genki-answer" data-value="${esc(value)}" ${f?'disabled':''}><span class="option-key">${i+1}</span><span ${/[ぁ-龯]/.test(value)?'lang="ja"':''}>${esc(value)}</span></button>`).join('')}</div>`;
  else if(q.type==='type')inputs=`<form id="genki-answer-form"><label for="genki-reading">Хираганой или латиницей</label><input id="genki-reading" name="reading" class="reading-input" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Твой ответ" maxlength="200" ${f?'readonly aria-readonly="true"':''} enterkeyhint="go" value="${f?esc(f.value):''}"><button class="primary wide" ${f?'disabled':''}>Проверить</button></form>`;
  else inputs=`<div class="sentence-builder"><div class="sentence-answer" lang="ja" aria-live="polite">${f?esc(f.value):draft.length?draft.map(i=>esc(q.tokens[i])).join(' '):'<span class="muted" lang="ru">Нажимай на слова по порядку</span>'}</div><div class="word-bank">${ordered(q.tokens,seed).map(({value,index})=>`<button class="token-button" lang="ja" data-action="genki-token" data-index="${index}" ${f||draft.includes(index)?'disabled':''}>${esc(value)}</button>`).join('')}</div><div class="builder-actions"><button class="text-button" data-action="genki-undo" ${f||!draft.length?'disabled':''}>Убрать последнее</button></div></div>`;
  body=`<section class="exercise-content genki-exercise"><div class="exercise-meta"><span class="eyebrow">${item.retry?'ПОВТОР ОШИБКИ':q.audio?'НА СЛУХ':q.type==='build'?'СОБЕРИ ФРАЗУ':q.type==='type'?'ЧТЕНИЕ':'ПРАКТИКА'}</span><span class="muted">${s.index+1} / ${s.questions.length}</span></div><h1>${esc(q.prompt)}</h1>${q.ja?`<div class="genki-prompt" lang="ja">${esc(q.ja)}</div>`:''}${q.ru?`<p class="question-subtitle">${esc(q.ru)}</p>`:''}${q.audio?(q.audio.startsWith('word-')?wordPlayer(q.audio):player(q.audio,'Послушать диалог')):''}${inputs}<div class="exercise-feedback ${f?(f.correct?'is-correct':'is-wrong'):''}" ${f?'role="status" aria-live="polite"':''}>${f?`<div class="feedback-main"><div><strong>${f.correct?'Верно':'Правильный ответ: '+esc(q.answer)}</strong><p>${esc(q.explanation)}${f.earned?' · +'+f.earned+' XP':''}</p></div></div>${!f.correct?'<p class="feedback-hint">Это задание повторится в занятии.</p>':''}<button class="primary wide" data-action="genki-next">Продолжить</button>`:''}</div></section>`;
 }
 const total=s.phase==='learn'?unit.cards.length:s.questions.length,at=s.phase==='learn'?s.cardIndex:s.index,fraction=s.phase==='result'?100:Math.round(at/Math.max(1,total)*100);
 return `<div class="lesson-shell"><header class="lesson-top"><button class="exit-button" data-action="genki-exit" aria-label="Выйти из занятия, сохранив прогресс">×</button><div class="lesson-top-center"><span>${esc(title)}</span><div class="session-track" role="progressbar" aria-label="Ход занятия" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${fraction}"><span style="width:${fraction}%"></span></div></div><span class="session-xp">${state.xp} XP</span></header><main id="main" tabindex="-1" class="lesson-main genki-main">${body}</main>${syncMarkup}</div>`;
}
